@Override
    protected EsqlConfiguration mutateInstance(EsqlConfiguration in) {
        ZoneId zoneId = in.zoneId();
        Locale locale = in.locale();
        String username = in.username();
        String clusterName = in.clusterName();
        QueryPragmas pragmas = in.pragmas();
        int resultTruncationMaxSize = in.resultTruncationMaxSize();
        int resultTruncationDefaultSize = in.resultTruncationDefaultSize();
        String query = in.query();
        boolean profile = in.profile();
        Map<String, Map<String, Column>> tables = in.tables();
        switch (between(0, 9)) {
            case 0 -> zoneId = randomValueOtherThan(zoneId, () -> randomZone().normalized());
            case 1 -> locale = randomValueOtherThan(in.locale(), () -> randomLocale(random()));
            case 2 -> username = randomAlphaOfLength(15);
            case 3 -> clusterName = randomAlphaOfLength(15);
            case 4 -> pragmas = new QueryPragmas(
                Settings.builder().put(QueryPragmas.EXCHANGE_BUFFER_SIZE.getKey(), between(1, 10)).build()
            );
            case 5 -> resultTruncationMaxSize += randomIntBetween(3, 10);
            case 6 -> resultTruncationDefaultSize += randomIntBetween(3, 10);
            case 7 -> query += randomAlphaOfLength(2);
            case 8 -> profile = false == profile;
            case 9 -> {
                while (true) {
                    Map<String, Map<String, Column>> newTables = null;
                    try {
                        newTables = randomTables();
                        if (false == tables.equals(newTables)) {
                            tables = newTables;
                            newTables = null;
                            break;
                        }
                    } finally {
                        if (newTables != null) {
                            Releasables.close(
                                Releasables.wrap(
                                    Iterators.flatMap(
                                        newTables.values().iterator(),
                                        columns -> Iterators.map(columns.values().iterator(), Column::values)
                                    )
                                )
                            );
                        }
                    }
                }
            }
        }
        return new EsqlConfiguration(
            zoneId,
            locale,
            username,
            clusterName,
            pragmas,
            resultTruncationMaxSize,
            resultTruncationDefaultSize,
            query,
            profile,
            tables
        );

    }

static {
        BlockFactory factory = new BlockFactory(new NoopCircuitBreaker(CircuitBreaker.REQUEST), BigArrays.NON_RECYCLING_INSTANCE);
        Map<String, Map<String, Column>> tables = new HashMap<>();
        try (
            IntBlock.Builder ints = factory.newIntBlockBuilder(10);
            LongBlock.Builder longs = factory.newLongBlockBuilder(10);
            BytesRefBlock.Builder names = factory.newBytesRefBlockBuilder(10);
        ) {
            for (int i = 0; i < 10; i++) {
                ints.appendInt(i);
                longs.appendLong(i);
                names.appendBytesRef(new BytesRef(switch (i) {
                    case 0 -> "zero";
                    case 1 -> "one";
                    case 2 -> "two";
                    case 3 -> "three";
                    case 4 -> "four";
                    case 5 -> "five";
                    case 6 -> "six";
                    case 7 -> "seven";
                    case 8 -> "eight";
                    case 9 -> "nine";
                    default -> throw new IllegalArgumentException();
                }));
            }

            IntBlock intsBlock = ints.build();
            LongBlock longsBlock = longs.build();
            BytesRefBlock namesBlock = names.build();
            tables.put(
                "int_number_names",
                Map.of("int", new Column(DataTypes.INTEGER, intsBlock), "name", new Column(DataTypes.KEYWORD, namesBlock))
            );
            tables.put(
                "long_number_names",
                Map.of("long", new Column(DataTypes.LONG, longsBlock), "name", new Column(DataTypes.KEYWORD, namesBlock))
            );
        }
        TABLES = unmodifiableMap(tables);
    }

/**
 * Looks up values from the associated {@code tables}.
 * The class is used only during the analysis phased, after which it is replaced by a {@code Join}.
 */
public class Lookup extends UnaryPlan {
    private final Expression tableName;
    private final List<NamedExpression> matchFields;
    // initialized during the analysis phase for output and validation
    // afterward, it is converted into a Join (BinaryPlan) hence why here it is not a child
    private final LocalRelation localRelation;
    private List<Attribute> lazyOutput;

    public Lookup(Source source, LogicalPlan child, Expression tableName, List<NamedExpression> matchFields) {
        this(source, child, tableName, matchFields, null);
    }

    public Lookup(Source source, LogicalPlan child, Expression tableName, List<NamedExpression> matchFields, LocalRelation localRelation) {
        super(source, child);
        this.tableName = tableName;
        this.matchFields = matchFields;
        this.localRelation = localRelation;
    }

    public Expression tableName() {
        return tableName;
    }

    public List<NamedExpression> matchFields() {
        return matchFields;
    }

    public LocalRelation localRelation() {
        return localRelation;
    }

    @Override
    public boolean expressionsResolved() {
        return tableName.resolved() && Resolvables.resolved(matchFields);
    }

    @Override
    public UnaryPlan replaceChild(LogicalPlan newChild) {
        return new Lookup(source(), newChild, tableName, matchFields);
    }

    @Override
    protected NodeInfo<? extends LogicalPlan> info() {
        return NodeInfo.create(this, Lookup::new, child(), tableName, matchFields);
    }

    @Override
    public List<Attribute> output() {
        if (lazyOutput == null) {
            List<? extends NamedExpression> rightSide = localRelation != null ? localRelation.output() : matchFields;
            lazyOutput = mergeOutputAttributes(child().output(), rightSide);
        }
        return lazyOutput;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }
        if (super.equals(o) == false) {
            return false;
        }
        Lookup lookup = (Lookup) o;
        return Objects.equals(tableName, lookup.matchFields)
            && Objects.equals(matchFields, lookup.matchFields)
            && Objects.equals(localRelation, lookup.localRelation);
    }

    @Override
    public int hashCode() {
        return Objects.hash(super.hashCode(), tableName, matchFields, localRelation);
    }
}

private LogicalPlan resolveLookup(Lookup l, List<Attribute> childrenOutput) {
            // check if the table exists before performing any resolution
            if (l.localRelation() == null) {
                return l;
            }

            // check the on field against both the child output and the inner relation
            List<NamedExpression> on = l.matchFields();
            List<NamedExpression> resolvedOn = new ArrayList<>(on.size());
            List<Attribute> localOutput = l.localRelation().output();

            for (NamedExpression ne : on) {
                if (ne instanceof UnresolvedAttribute ua && ua.customMessage() == false) {
                    ne = maybeResolveAttribute(ua, localOutput);
                    // can't find the field inside the local relation
                    if (ne instanceof UnresolvedAttribute lua) {
                        // adjust message
                        ne = lua.withUnresolvedMessage(
                            lua.unresolvedMessage().replace("Unknown column", "Unknown column in lookup target")
                        );
                    }
                    // check also the child output by resolving to it
                    else {
                        ne = maybeResolveAttribute(ua, localOutput);
                    }
                }

                resolvedOn.add(ne);
            }

            return new Lookup(l.source(), l.child(), l.tableName(), resolvedOn, l.localRelation());
        }

if (plan.childrenResolved() == false) {
                return plan;
            }

public class HashJoinExec extends UnaryExec implements EstimatesRowSize {
    private final Attribute tableName;
    private final List<Attribute> matchFields;
    private final List<TableColumnAttribute> matchValues;
    private final List<TableColumnAttribute> mergeValues;

    public HashJoinExec(
        Source source,
        PhysicalPlan child,
        Attribute tableName,
        List<Attribute> matchFields,
        @Nullable List<TableColumnAttribute> matchValues,
        @Nullable List<TableColumnAttribute> mergeValues
    ) {
        super(source, child);
        this.tableName = tableName;
        this.matchFields = matchFields;
        this.matchValues = matchValues;
        this.mergeValues = mergeValues;
    }

    public List<Attribute> matchFields() {
        return matchFields;
    }

    public List<TableColumnAttribute> matchValues() {
        return matchValues;
    }

    public List<TableColumnAttribute> mergeValues() {
        return mergeValues;
    }

    @Override
    public PhysicalPlan estimateRowSize(State state) {
        state.add(false, mergeValues);
        return this;
    }

    @Override
    public List<Attribute> output() {
        return mergeOutputAttributes(mergeValues, child().output());
    }

    @Override
    public HashJoinExec replaceChild(PhysicalPlan newChild) {
        return new HashJoinExec(source(), newChild, tableName, matchFields, matchValues, mergeValues);
    }

    @Override
    protected NodeInfo<? extends PhysicalPlan> info() {
        return NodeInfo.create(this, HashJoinExec::new, child(), tableName, matchFields, matchValues, mergeValues);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }
        if (super.equals(o) == false) {
            return false;
        }
        HashJoinExec lookup = (HashJoinExec) o;
        return Objects.equals(tableName, lookup.matchFields)
            && Objects.equals(matchFields, lookup.matchFields)
            && Objects.equals(matchValues, lookup.matchValues)
            && Objects.equals(mergeValues, lookup.mergeValues);
    }

    @Override
    public int hashCode() {
        return Objects.hash(super.hashCode(), tableName, matchFields, matchValues, mergeValues);
    }
}

public class Join extends BinaryPlan {

    private final JoinType type;
    private final Expression condition;
    private List<Attribute> lazyOutput;

    public Join(Source source, LogicalPlan left, LogicalPlan right, JoinType type, Expression condition) {
        super(source, left, right);
        this.type = type;
        this.condition = condition;
    }

    @Override
    protected NodeInfo<Join> info() {
        return NodeInfo.create(this, Join::new, left(), right(), type, condition);
    }

    @Override
    public Join replaceChildren(List<LogicalPlan> newChildren) {
        return new Join(source(), newChildren.get(0), newChildren.get(1), type, condition);
    }

    public Join replaceChildren(LogicalPlan left, LogicalPlan right) {
        return new Join(source(), left, right, type, condition);
    }

    public JoinType type() {
        return type;
    }

    public Expression condition() {
        return condition;
    }

    @Override
    public List<Attribute> output() {
        if (lazyOutput == null) {
            lazyOutput = computeOutput();
        }
        return lazyOutput;
    }

    private List<Attribute> computeOutput() {
        if (type == LEFT) {
            // right side can be null
            return NamedExpressions.mergeOutputAttributes(left().output(), makeNullable(right().output()));
        }
        if (type == RIGHT) {
            // left side can be null
            return NamedExpressions.mergeOutputAttributes(makeNullable(left().output()), right().output());
        }
        if (type == FULL) {
            // both sides can be null
            return NamedExpressions.mergeOutputAttributes(makeNullable(left().output()), makeNullable(right().output()));
        }
        // the rest - INNER, CROSS
        return NamedExpressions.mergeOutputAttributes(left().output(), right().output());
    }

    private static List<Attribute> makeNullable(List<Attribute> output) {
        List<Attribute> out = new ArrayList<>(output.size());
        for (Attribute a : output) {
            out.add(a.withNullability(Nullability.TRUE));
        }
        return out;
    }

    @Override
    public boolean expressionsResolved() {
        return condition == null || condition.resolved();
    }

    public boolean duplicatesResolved() {
        return left().outputSet().intersect(right().outputSet()).isEmpty();
    }

    @Override
    public boolean resolved() {
        // resolve the join if
        // - the children are resolved
        // - there are no conflicts in output
        // - the condition (if present) is resolved to a boolean
        return childrenResolved()
            && duplicatesResolved()
            && expressionsResolved()
            && (condition == null || DataTypes.BOOLEAN == condition.dataType());
    }

    @Override
    public int hashCode() {
        return Objects.hash(type, condition, left(), right());
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) {
            return true;
        }
        if (obj == null || getClass() != obj.getClass()) {
            return false;
        }

        Join other = (Join) obj;

        return Objects.equals(type, other.type)
            && Objects.equals(condition, other.condition)
            && Objects.equals(left(), other.left())
            && Objects.equals(right(), other.right());
    }
}

private static class ResolveLookup extends ParameterizedAnalyzerRule<Lookup, AnalyzerContext> {

        @Override
        protected LogicalPlan rule(Lookup lookup, AnalyzerContext context) {
            // the parser passes the string wrapped in a literal
            Source source = lookup.source();
            Expression tableNameExpression = lookup.tableName();
            String tableName = lookup.tableName().toString();
            Map<String, Map<String, Column>> tables = context.configuration().tables();
            LocalRelation localRelation = null;

            if (tables.containsKey(tableName) == false) {
                String message = "Unknown table [" + tableName + "]";
                // typos check
                List<String> potentialMatches = StringUtils.findSimilar(tableName, tables.keySet());
                if (CollectionUtils.isEmpty(potentialMatches) == false) {
                    message = UnresolvedAttribute.errorMessage(tableName, potentialMatches).replace("column", "table");
                }
                tableNameExpression = new UnresolvedAttribute(tableNameExpression.source(), tableName, null, message);
            }
            // wrap the table in a local relationship for idiomatic field resolution
            else {
                localRelation = tableMapAsRelation(source, tables.get(tableName));
                // postpone the resolution for ResolveRefs
            }

            return new Lookup(source, lookup.child(), tableNameExpression, lookup.matchFields(), localRelation);
        }

        private LocalRelation tableMapAsRelation(Source source, Map<String, Column> mapTable) {
            Block[] blocks = new Block[mapTable.size()];

            List<Attribute> attributes = new ArrayList<>(blocks.length);
            int i = 0;
            for (Map.Entry<String, Column> entry : mapTable.entrySet()) {
                String name = entry.getKey();
                Column column = entry.getValue();
                // create a fake ES field - alternative is to use a ReferenceAttribute
                EsField field = new EsField(name, column.type(), null, false, false);
                attributes.add(new FieldAttribute(source, null, name, field));
                // prepare the block for the supplier
                blocks[i++] = column.values();
            }
            LocalSupplier supplier = LocalSupplier.of(blocks);
            return new LocalRelation(source, attributes, supplier);
        }
    }

