public class HashJoinExec extends UnaryExec implements EstimatesRowSize {
    private final Attribute tableName;
    private final List<Attribute> matchFields;
    private final List<TableColumnAttribute> matchValues;
    private final List<TableColumnAttribute> mergeValues;

    public HashJoinExec(
        Source source,
        PhysicalPlan child,
        Attribute tableName,
        List<Attribute> matchFields,
        @Nullable List<TableColumnAttribute> matchValues,
        @Nullable List<TableColumnAttribute> mergeValues
    ) {
        super(source, child);
        this.tableName = tableName;
        this.matchFields = matchFields;
        this.matchValues = matchValues;
        this.mergeValues = mergeValues;
    }

    public List<Attribute> matchFields() {
        return matchFields;
    }

    public List<TableColumnAttribute> matchValues() {
        return matchValues;
    }

    public List<TableColumnAttribute> mergeValues() {
        return mergeValues;
    }

    @Override
    public PhysicalPlan estimateRowSize(State state) {
        state.add(false, mergeValues);
        return this;
    }

    @Override
    public List<Attribute> output() {
        return mergeOutputAttributes(mergeValues, child().output());
    }

    @Override
    public HashJoinExec replaceChild(PhysicalPlan newChild) {
        return new HashJoinExec(source(), newChild, tableName, matchFields, matchValues, mergeValues);
    }

    @Override
    protected NodeInfo<? extends PhysicalPlan> info() {
        return NodeInfo.create(this, HashJoinExec::new, child(), tableName, matchFields, matchValues, mergeValues);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }
        if (super.equals(o) == false) {
            return false;
        }
        HashJoinExec lookup = (HashJoinExec) o;
        return Objects.equals(tableName, lookup.matchFields)
            && Objects.equals(matchFields, lookup.matchFields)
            && Objects.equals(matchValues, lookup.matchValues)
            && Objects.equals(mergeValues, lookup.mergeValues);
    }

    @Override
    public int hashCode() {
        return Objects.hash(super.hashCode(), tableName, matchFields, matchValues, mergeValues);
    }
}

public class Join extends BinaryPlan {

    private final JoinType type;
    private final Expression condition;
    private List<Attribute> lazyOutput;

    public Join(Source source, LogicalPlan left, LogicalPlan right, JoinType type, Expression condition) {
        super(source, left, right);
        this.type = type;
        this.condition = condition;
    }

    @Override
    protected NodeInfo<Join> info() {
        return NodeInfo.create(this, Join::new, left(), right(), type, condition);
    }

    @Override
    public Join replaceChildren(List<LogicalPlan> newChildren) {
        return new Join(source(), newChildren.get(0), newChildren.get(1), type, condition);
    }

    public Join replaceChildren(LogicalPlan left, LogicalPlan right) {
        return new Join(source(), left, right, type, condition);
    }

    public JoinType type() {
        return type;
    }

    public Expression condition() {
        return condition;
    }

    @Override
    public List<Attribute> output() {
        if (lazyOutput == null) {
            lazyOutput = computeOutput();
        }
        return lazyOutput;
    }

    private List<Attribute> computeOutput() {
        if (type == LEFT) {
            // right side can be null
            return NamedExpressions.mergeOutputAttributes(left().output(), makeNullable(right().output()));
        }
        if (type == RIGHT) {
            // left side can be null
            return NamedExpressions.mergeOutputAttributes(makeNullable(left().output()), right().output());
        }
        if (type == FULL) {
            // both sides can be null
            return NamedExpressions.mergeOutputAttributes(makeNullable(left().output()), makeNullable(right().output()));
        }
        // the rest - INNER, CROSS
        return NamedExpressions.mergeOutputAttributes(left().output(), right().output());
    }

    private static List<Attribute> makeNullable(List<Attribute> output) {
        List<Attribute> out = new ArrayList<>(output.size());
        for (Attribute a : output) {
            out.add(a.withNullability(Nullability.TRUE));
        }
        return out;
    }

    @Override
    public boolean expressionsResolved() {
        return condition == null || condition.resolved();
    }

    public boolean duplicatesResolved() {
        return left().outputSet().intersect(right().outputSet()).isEmpty();
    }

    @Override
    public boolean resolved() {
        // resolve the join if
        // - the children are resolved
        // - there are no conflicts in output
        // - the condition (if present) is resolved to a boolean
        return childrenResolved()
            && duplicatesResolved()
            && expressionsResolved()
            && (condition == null || DataTypes.BOOLEAN == condition.dataType());
    }

    @Override
    public int hashCode() {
        return Objects.hash(type, condition, left(), right());
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) {
            return true;
        }
        if (obj == null || getClass() != obj.getClass()) {
            return false;
        }

        Join other = (Join) obj;

        return Objects.equals(type, other.type)
            && Objects.equals(condition, other.condition)
            && Objects.equals(left(), other.left())
            && Objects.equals(right(), other.right());
    }
}

private static class ResolveLookup extends ParameterizedAnalyzerRule<Lookup, AnalyzerContext> {

        @Override
        protected LogicalPlan rule(Lookup lookup, AnalyzerContext context) {
            // the parser passes the string wrapped in a literal
            Source source = lookup.source();
            Expression tableNameExpression = lookup.tableName();
            String tableName = lookup.tableName().toString();
            Map<String, Map<String, Column>> tables = context.configuration().tables();
            LocalRelation localRelation = null;

            if (tables.containsKey(tableName) == false) {
                String message = "Unknown table [" + tableName + "]";
                // typos check
                List<String> potentialMatches = StringUtils.findSimilar(tableName, tables.keySet());
